B.atv=new A.U("M\u1ee5c ti\xeau","\u0110\u01b0a m\u1ed7i m\u1eb7t v\u1ec1 m\u1ed9t m\xe0u duy nh\u1ea5t.")
B.asS=new A.U("Xoay m\u1ed9t l\u1edbp","\u0110\u1eb7t ng\xf3n tay l\xean m\u1ed9t \xf4 c\u1ee7a kh\u1ed1i r\u1ed3i vu\u1ed1t theo h\u01b0\u1edbng mu\u1ed1n xoay. L\u1edbp ch\u1ee9a \xf4 \u0111\xf3 s\u1ebd xoay 90\xb0.")
B.asB=new A.U("Xoay g\xf3c nh\xecn",'Vu\u1ed1t \u1edf v\xf9ng tr\u1ed1ng b\xean ngo\xe0i kh\u1ed1i \u0111\u1ec3 xoay camera. Ch\u1ee5m/m\u1edf hai ng\xf3n \u0111\u1ec3 thu ph\xf3ng. N\xfat "\u0110\u1eb7t l\u1ea1i camera" \u0111\u01b0a v\u1ec1 g\xf3c m\u1eb7c \u0111\u1ecbnh.')
B.asr=new A.U("K\xfd hi\u1ec7u (n\xe2ng cao)",'D\xf9ng trong "\u0110i\u1ec1u khi\u1ec3n n\xe2ng cao" v\xe0 khi nh\u1eadp x\xe1o tr\u1ed9n. U (tr\xean), D (d\u01b0\u1edbi), L (tr\xe1i), R (ph\u1ea3i), F (tr\u01b0\u1edbc), B (sau). Kh\xf4ng d\u1ea5u = xoay theo chi\u1ec1u kim \u0111\u1ed3ng h\u1ed3 khi nh\xecn th\u1eb3ng v\xe0o m\u1eb7t \u0111\xf3; d\u1ea5u \' = ng\u01b0\u1ee3c chi\u1ec1u; 2 = xoay 180\xb0.')
B.atc=new A.U("\u0110i\u1ec3m",'\u0110i\u1ec3m = max(100, 5000 \u2212 5\xd7gi\xe2y \u2212 10\xd7s\u1ed1 n\u01b0\u1edbc) \u2212 150\xd7s\u1ed1 g\u1ee3i \xfd. D\xf9ng "T\u1ef1 gi\u1ea3i" th\xec v\xe1n \u0111\u01b0\u1ee3c ghi l\xe0 c\xf3 tr\u1ee3 gi\xfap, 0 \u0111i\u1ec3m v\xe0 kh\xf4ng l\xean b\u1ea3ng x\u1ebfp h\u1ea1ng.')
B.ast=new A.U("Tr\u1ee3 l\xfd gi\u1ea3i",'B\u1ea5m "G\u1ee3i \xfd": l\u1edbp c\u1ea7n xoay s\xe1ng l\xean tr\xean kh\u1ed1i k\xe8m m\u0169i t\xean ch\u1ec9 h\u01b0\u1edbng. Xoay \u0111\xfang th\xec g\u1ee3i \xfd t\u1ef1 sang b\u01b0\u1edbc sau; xoay kh\xe1c th\xec tr\u1ee3 l\xfd t\u1ef1 t\xednh l\u1ea1i theo kh\u1ed1i hi\u1ec7n t\u1ea1i. M\xe0n "Tr\u1ee3 l\xfd gi\u1ea3i" cho \u0111i t\u1eebng b\u01b0\u1edbc (Tr\u01b0\u1edbc/Ti\u1ebfp), t\u1ef1 gi\u1ea3i, t\u1ea1m d\u1eebng, \u0111\u1ed5i t\u1ed1c \u0111\u1ed9. H\u01b0\u1edbng d\u1eabn \u0111\u01b0\u1ee3c t\xednh ngay tr\xean m\xe1y, kh\xf4ng c\u1ea7n m\u1ea1ng, nh\u01b0ng kh\xf4ng ph\u1ea3i l\xfac n\xe0o c\u0169ng ng\u1eafn nh\u1ea5t.')
B.at_=new A.U("Ho\xe0n t\xe1c","Ho\xe0n t\xe1c/l\xe0m l\u1ea1i kh\xf4ng gi\u1edbi h\u1ea1n. M\u1ed7i l\u1ea7n ho\xe0n t\xe1c \u0111\u01b0\u1ee3c t\xednh l\xe0 m\u1ed9t l\u1ed7i trong th\u1ed1ng k\xea.")
B.afg=s([B.atv,B.asS,B.asB,B.asr,B.atc,B.ast,B.at_],t.Wy)
B.asX=new A.U("Lu\u1eadt","\u0110i\u1ec1n s\u1ed1 1\u20139 sao cho m\u1ed7i h\xe0ng, m\u1ed7i c\u1ed9t v\xe0 m\u1ed7i kh\u1ed1i 3\xd73 ch\u1ee9a \u0111\u1ee7 1\u20139 kh\xf4ng l\u1eb7p l\u1ea1i.")
B.as0=new A.U("\u0110\u1ed9 kh\xf3",'M\u1ed7i \u0111\u1ec1 c\xf3 \u0111\xfang m\u1ed9t l\u1eddi gi\u1ea3i. \u0110\u1ed9 kh\xf3 \u0111\u01b0\u1ee3c ch\u1ea5m b\u1eb1ng k\u1ef9 thu\u1eadt c\u1ea7n d\xf9ng: D\u1ec5 = ch\u1ec9 c\u1ea7n "\xf4 duy nh\u1ea5t"; Trung b\xecnh = c\u1ea7n "v\u1ecb tr\xed duy nh\u1ea5t"; Kh\xf3 = c\u1ea7n lo\u1ea1i tr\u1eeb c\u1eb7p/kh\xf3a ho\u1eb7c th\u1eed-sai.')
B.at3=new A.U("Ghi ch\xfa",'B\u1eadt ch\u1ebf \u0111\u1ed9 "Ghi ch\xfa" \u0111\u1ec3 \u0111i\u1ec1n s\u1ed1 nh\u1ecf l\xe0m nh\xe1p. Khi \u0111i\u1ec1n s\u1ed1 ch\xednh, c\xe1c ghi ch\xfa tr\xf9ng trong c\xf9ng h\xe0ng/c\u1ed9t/kh\u1ed1i t\u1ef1 xo\xe1.')
B.asq=new A.U("\u0110i\u1ec3m","\u0110i\u1ec3m c\u01a1 b\u1ea3n D\u1ec5 1000 / Trung b\xecnh 2000 / Kh\xf3 3500, tr\u1eeb 2 \u0111i\u1ec3m m\u1ed7i gi\xe2y, 50 \u0111i\u1ec3m m\u1ed7i l\u1ed7i, 100 \u0111i\u1ec3m m\u1ed7i g\u1ee3i \xfd (t\u1ed1i thi\u1ec3u 100).")
B.ahz=s([B.asX,B.as0,B.at3,B.asq],t.Wy)
B.atD=new A.U("Lu\u1eadt","T\u1ef1 do gh\xe9p tranh, k\xe9o th\u1ea3 v\xe0 k\u1ebft n\u1ed1i c\xe1c m\u1ea3nh theo \xfd b\u1ea1n. M\u1ea3nh n\u1eb1m nguy\xean t\u1ea1i n\u01a1i th\u1ea3. B\u1eadt H\xfat c\u1ea1nh \u0111\u1ec3 n\u1ed1i nh\u1eb9 hai c\u1ea1nh \u0111\xfang; k\xe9o m\u1ed9t m\u1ea3nh \u0111\u1ec3 di chuy\u1ec3n c\u1ea3 nh\xf3m, gi\u1eef l\xe2u \u0111\u1ec3 t\xe1ch ri\xeang. C\xf3 th\u1ec3 gh\xe9p tranh \u1edf b\u1ea5t k\u1ef3 \u0111\xe2u, ph\xf3ng to v\xe0 k\xe9o b\xe0n; \u1ea3nh m\u1eabu n\u1eb1m ri\xeang.")
B.as_=new A.U("C\u1ea5p \u0111\u1ed9","3\xd73 (9 m\u1ea3nh) \u0111\u1ebfn 6\xd76 (36 m\u1ea3nh). C\xf3 th\u1ec3 xem \u1ea3nh m\u1eabu b\u1ea5t k\u1ef3 l\xfac n\xe0o.")
B.asU=new A.U("\u0110i\u1ec3m","500 + 30\xd7s\u1ed1 m\u1ea3nh, tr\u1eeb 1 \u0111i\u1ec3m m\u1ed7i gi\xe2y (t\u1ed1i thi\u1ec3u 50). Th\u1ea3 th\u1eed v\u1ecb tr\xed, xem \u1ea3nh m\u1eabu v\xe0 t\xecm c\u1eb7p m\u1ea3nh \u0111\u1ec1u kh\xf4ng tr\u1eeb \u0111i\u1ec3m, kh\xf4ng di chuy\u1ec3n m\u1ea3nh h\u1ed9 b\u1ea1n.")
B.ady=s([B.atD,B.as_,B.asU],t.Wy)
B.atw=new A.U("Lu\u1eadt","B\xe0n 15\xd715. Ai c\xf3 5 qu\xe2n li\xean ti\u1ebfp (ngang, d\u1ecdc ho\u1eb7c ch\xe9o) tr\u01b0\u1edbc th\xec th\u1eafng. H\u1ebft ch\u1ed7 m\xe0 kh\xf4ng ai th\u1eafng th\xec ho\xe0. X lu\xf4n \u0111i tr\u01b0\u1edbc.")
B.ato=new A.U("Qu\xe2n X/O","M\u1ed7i v\xe1n m\u1edbi, h\u1ec7 th\u1ed1ng b\u1ed1c ng\u1eabu nhi\xean cho b\u1ea1n qu\xe2n X ho\u1eb7c O. X lu\xf4n \u0111i tr\u01b0\u1edbc: n\u1ebfu b\u1ea1n l\xe0 O th\xec m\xe1y \u0111i tr\u01b0\u1edbc. V\xe1n ti\u1ebfp t\u1ee5c t\u1eeb b\u1ea3n l\u01b0u gi\u1eef nguy\xean qu\xe2n v\xe0 l\u01b0\u1ee3t.")
B.asE=new A.U("\u0110\u1ed9 kh\xf3","D\u1ec5: ph\xf9 h\u1ee3p cho ng\u01b0\u1eddi m\u1edbi b\u1eaft \u0111\u1ea7u, m\xe1y ch\u01a1i \u0111\u01a1n gi\u1ea3n v\xe0 \u0111\xf4i khi m\u1eafc l\u1ed7i. V\u1eeba: m\xe1y bi\u1ebft ph\xf2ng th\u1ee7 v\xe0 t\xecm c\u01a1 h\u1ed9i chi\u1ebfn th\u1eafng. Kh\xf3: m\xe1y t\xednh to\xe1n c\u1ea9n th\u1eadn h\u01a1n v\xe0 \u0111\u01b0a ra nh\u1eefng n\u01b0\u1edbc \u0111i kh\xf3 \u0111\u1ed1i ph\xf3.")
B.att=new A.U("Sai l\u1ea7m l\u1edbn","\u0110\u01b0\u1ee3c t\xednh khi b\u1ea1n b\u1ecf l\u1ee1 n\u01b0\u1edbc th\u1eafng ngay, ho\u1eb7c kh\xf4ng ch\u1eb7n n\u01b0\u1edbc th\u1eafng ngay c\u1ee7a \u0111\u1ed1i th\u1ee7 trong khi v\u1eabn c\xf2n ch\u1eb7n \u0111\u01b0\u1ee3c. N\u1ebfu \u0111\u1ed1i th\u1ee7 \u0111\xe3 c\xf3 hai \u0111\u1ea7u th\u1eafng (kh\xf4ng th\u1ec3 c\u1ee9u) th\xec kh\xf4ng t\xednh.")
B.at0=new A.U("\u0110i\u1ec3m","Th\u1eafng: D\u1ec5 300 / V\u1eeba 600 / Kh\xf3 1000 + th\u01b0\u1edfng th\u1eafng nhanh max(0, 300 \u2212 3\xd7s\u1ed1 n\u01b0\u1edbc), tr\u1eeb 100 m\u1ed7i g\u1ee3i \xfd. Ho\xe0: 1/3 \u0111i\u1ec3m c\u01a1 b\u1ea3n. Thua: 0.")
