B.asg=new A.U("Rubik \u2014 tr\u1ee3 l\xfd gi\u1ea3i",'Thu\u1eadt to\xe1n Two-Phase (Kociemba) ch\u1ea1y offline trong lu\u1ed3ng n\u1ec1n; l\u1eddi gi\u1ea3i \u0111\u01b0\u1ee3c \xe1p th\u1eed l\xean kh\u1ed1i tr\u01b0\u1edbc khi d\xf9ng. L\u1eddi gi\u1ea3i th\u01b0\u1eddng \u2264 22 n\u01b0\u1edbc nh\u01b0ng kh\xf4ng \u0111\u1ea3m b\u1ea3o ng\u1eafn nh\u1ea5t. "T\u1ed1i \u01b0u s\u1ed1 n\u01b0\u1edbc" ch\u1ec9 t\xecm l\u1eddi gi\u1ea3i ng\u1eafn h\u01a1n trong th\u1eddi gian cho ph\xe9p.')
B.asG=new A.U("Rubik \u2014 c\xe1ch \u0111\u1ebfm l\u01b0\u1ee3t",'"S\u1ed1 l\u01b0\u1ee3t xoay" l\xe0 th\u01b0\u1edbc \u0111o HTM: m\u1ed7i l\u1ea7n xoay m\u1ed9t m\u1eb7t 90\xb0 ho\u1eb7c 180\xb0 t\xednh 1. Th\u01b0\u1edbc \u0111o QTM t\xednh xoay 180\xb0 l\xe0 2. S\u1ed1 Th\u1ea7n: m\u1ecdi tr\u1ea1ng th\xe1i gi\u1ea3i \u0111\u01b0\u1ee3c trong \u2264 20 HTM (\u2264 26 QTM).')
B.atd=new A.U("Caro \u2014 m\xe1y ch\u01a1i th\u1ebf n\xe0o","D\u1ec5: \u0111\xe1nh gi\xe1 nhanh t\u1eebng \xf4 c\xf3 y\u1ebfu t\u1ed1 ng\u1eabu nhi\xean, kh\xf4ng t\xednh tr\u01b0\u1edbc. V\u1eeba: lu\xf4n th\u1eafng ngay/ch\u1eb7n n\u01b0\u1edbc b\u1ed1n, minimax 2 l\u1edbp tr\xean 10 \u1ee9ng vi\xean t\u1ed1t nh\u1ea5t. Kh\xf3: minimax alpha\u2013beta \u0111\xe0o s\xe2u d\u1ea7n t\u1edbi 8 l\u1edbp, s\u1eafp x\u1ebfp n\u01b0\u1edbc theo heuristic, gi\u1edbi h\u1ea1n 1,5 gi\xe2y m\u1ed7i n\u01b0\u1edbc. T\u1ea5t c\u1ea3 ch\u1ea1y offline trong lu\u1ed3ng n\u1ec1n.")
B.asA=new A.U("Sudoku \u2014 ch\u1ea5m \u0111\u1ed9 kh\xf3","M\u1ed7i \u0111\u1ec1 c\xf3 \u0111\xfang m\u1ed9t l\u1eddi gi\u1ea3i; \u0111\u1ed9 kh\xf3 ch\u1ea5m theo k\u1ef9 thu\u1eadt c\u1ea7n d\xf9ng (\xf4 duy nh\u1ea5t, v\u1ecb tr\xed duy nh\u1ea5t, lo\u1ea1i tr\u1eeb c\u1eb7p/kho\xe1 ho\u1eb7c th\u1eed-sai).")
B.afT=s([B.asg,B.asG,B.atd,B.asA],t.Wy)
B.asC=new A.U("T\xe0i kho\u1ea3n","Kh\xf4ng b\u1eaft bu\u1ed9c. Ch\u1ebf \u0111\u1ed9 kh\xe1ch ch\u01a1i \u0111\u1ea7y \u0111\u1ee7 offline. Khi \u0111\u0103ng nh\u1eadp, k\u1ebft qu\u1ea3 \u0111\u01b0\u1ee3c \u0111\u1ed3ng b\u1ed9; n\u1ebfu m\u1ea5t m\u1ea1ng, k\u1ebft qu\u1ea3 \u0111\u01b0\u1ee3c gi\u1eef tr\xean m\xe1y v\xe0 g\u1eedi l\u1ea1i sau.")
B.asw=new A.U("Ch\u1ed1ng gian l\u1eadn","M\xe1y ch\u1ee7 t\u1ef1 t\xednh l\u1ea1i \u0111i\u1ec3m v\xe0 ki\u1ec3m tra t\xednh h\u1ee3p l\u1ec7 (v\xed d\u1ee5: l\u1eddi gi\u1ea3i Rubik ph\u1ea3i th\u1ef1c s\u1ef1 gi\u1ea3i \u0111\u01b0\u1ee3c x\xe1o tr\u1ed9n).")
B.atz=new A.U("Th\xe1ch \u0111\u1ea5u","Hai ng\u01b0\u1eddi gi\u1ea3i c\xf9ng m\u1ed9t x\xe1o tr\u1ed9n Rubik. L\u1eddi gi\u1ea3i t\u1ef1 l\u1ef1c lu\xf4n x\u1ebfp tr\xean l\u1eddi gi\u1ea3i c\xf3 tr\u1ee3 gi\xfap; c\xf9ng lo\u1ea1i th\xec ai nhanh h\u01a1n th\u1eafng.")
B.at1=new A.U("G\u1ea7n \u0111\xe2y","Ch\u1ec9 ho\u1ea1t \u0111\u1ed9ng khi b\u1ea1n b\u1eadt. \u1ee8ng d\u1ee5ng l\u1ea5y v\u1ecb tr\xed g\u1ea7n \u0111\xfang (~1 km) m\u1ed9t l\u1ea7n khi b\u1ea1n m\u1edf m\xe0n h\xecnh, kh\xf4ng theo d\xf5i li\xean t\u1ee5c. Ng\u01b0\u1eddi kh\xe1c ch\u1ec9 th\u1ea5y kho\u1ea3ng c\xe1ch \u01b0\u1edbc l\u01b0\u1ee3ng, kh\xf4ng th\u1ea5y to\u1ea1 \u0111\u1ed9.")
B.asT=new A.U("Tr\xf2 chuy\u1ec7n","B\u1ea1n c\xf3 th\u1ec3 ch\u1eb7n ho\u1eb7c b\xe1o c\xe1o ng\u01b0\u1eddi d\xf9ng b\u1ea5t k\u1ef3 l\xfac n\xe0o.")
B.ajI=s([B.asC,B.asw,B.atz,B.at1,B.asT],t.Wy)
